import os
from datetime import datetime

def list_logs_in_range(log_dir, start_date, end_date):
    if not os.path.isdir(log_dir):
        raise NotADirectoryError(f"Directory not found: {log_dir}")

    # Parse dates to ensure valid format and enable comparison
    try:
        start = datetime.strptime(start_date, "%Y-%m-%d")
        end = datetime.strptime(end_date, "%Y-%m-%d")
    except ValueError as e:
        raise ValueError("Dates must be in 'YYYY-MM-DD' format") from e

    if start > end:
        raise ValueError("start_date cannot be after end_date")

    try:
        files = os.listdir(log_dir)
    except OSError as e:
        raise RuntimeError(f"Failed to list directory: {log_dir}") from e

    matching_files = []

    for filename in files:
        # Expected format: app-YYYY-MM-DD.log
        if filename.startswith("app-") and filename.endswith(".log"):
            date_str = filename[4:-4]
            try:
                file_date = datetime.strptime(date_str, "%Y-%m-%d")
            except ValueError:
                continue

            if start <= file_date <= end:
                matching_files.append(filename)

    return sorted(matching_files)

