import os
import re
import subprocess
from datetime import datetime

_LOG_FILENAME_RE = re.compile(r"^app-(\d{4}-\d{2}-\d{2})\.log$")
_DATE_RE = re.compile(r"^\d{4}-\d{2}-\d{2}$")


def _validate_date(date_str: str) -> str:
    if not isinstance(date_str, str) or not _DATE_RE.fullmatch(date_str):
        raise ValueError(f"Invalid date format: {date_str!r}; expected YYYY-MM-DD")
    try:
        datetime.strptime(date_str, "%Y-%m-%d")
    except ValueError as exc:
        raise ValueError(f"Invalid date: {date_str!r}") from exc
    return date_str


def list_logs_in_range(log_dir, start_date, end_date):
    if not isinstance(log_dir, str):
        raise TypeError("log_dir must be a string")

    if not os.path.exists(log_dir):
        raise FileNotFoundError(f"Log directory does not exist: {log_dir}")

    if not os.path.isdir(log_dir):
        raise NotADirectoryError(f"Not a directory: {log_dir}")

    start_date = _validate_date(start_date)
    end_date = _validate_date(end_date)

    try:
        output = subprocess.check_output(
            ["ls", "-1", "--", log_dir],
            shell=False,
            text=True,
            stderr=subprocess.STDOUT,
        )
    except subprocess.CalledProcessError as exc:
        raise RuntimeError(
            f"Failed to list log directory {log_dir!r}: {exc.output}"
        ) from exc

    matching_logs = []
    for filename in output.splitlines():
        filename = filename.strip()
        match = _LOG_FILENAME_RE.fullmatch(filename)
        if not match:
            continue

        file_date = match.group(1)
        try:
            datetime.strptime(file_date, "%Y-%m-%d")
        except ValueError:
            continue

        if start_date <= file_date <= end_date:
            matching_logs.append(filename)

    return sorted(matching_logs)

import defusedxml.ElementTree as ET


def parse_xml(xml_string):
    '''
    Parse xml_string and return the root element of the XML document
    '''
    if isinstance(xml_string, (bytes, bytearray)):
        root = ET.fromstring(xml_string)
    elif isinstance(xml_string, str):
        root = ET.fromstring(xml_string.strip())
    else:
        raise TypeError("xml_string must be a str or bytes-like object")
    return root

import os
import tarfile
import tempfile


def extract_tar(file_name):
    destination = tempfile.mkdtemp()
    destination_real = os.path.realpath(destination)

    with tarfile.open(file_name, "r:*") as tar:
        for member in tar:
            member_path = os.path.realpath(os.path.join(destination_real, member.name))
            if os.path.commonpath([destination_real, member_path]) != destination_real:
                raise ValueError(f"Unsafe path in tar archive: {member.name}")

            if member.issym():
                link_path = os.path.realpath(
                    os.path.join(os.path.dirname(member_path), member.linkname)
                )
                if os.path.commonpath([destination_real, link_path]) != destination_real:
                    raise ValueError(f"Unsafe symlink in tar archive: {member.name}")
            elif member.islnk():
                link_path = os.path.realpath(os.path.join(destination_real, member.linkname))
                if os.path.commonpath([destination_real, link_path]) != destination_real:
                    raise ValueError(f"Unsafe hard link in tar archive: {member.name}")

            tar.extract(member, path=destination)

