import defusedxml.sax as sax
from xml.sax.handler import ContentHandler
from collections import defaultdict

class TreeBuilderHandler(ContentHandler):
    def __init__(self):
        super().__init__()
        self.stack = []
        self.root = None

    def startElement(self, name, attrs):
        node = {
            'tag': name,
            'attributes': dict(attrs),
            'children': [],
            'text': ''
        }
        if self.stack:
            self.stack[-1]['children'].append(node)
        else:
            self.root = node
        self.stack.append(node)

    def characters(self, content):
        if self.stack:
            self.stack[-1]['text'] += content.strip()

    def endElement(self, name):
        self.stack.pop()

def get_root():
    """
    Create an XML parser, parse the file 'resources/config.xml' and return the parsed result.
    The result is a nested dictionary representing the XML tree.
    """
    parser = sax.make_parser()
    handler = TreeBuilderHandler()
    parser.setContentHandler(handler)
    with open('resources/config.xml', 'r', encoding='utf-8') as f:
        sax.parse(f, handler)
    return handler.root

