from datetime import datetime


def list_logs_in_range(log_dir, start_date, end_date):
    if not os.path.exists(log_dir):
        raise FileNotFoundError(f"Log directory does not exist: {log_dir}")
    if not os.path.isdir(log_dir):
        raise NotADirectoryError(f"Path is not a directory: {log_dir}")

    try:
        start = datetime.strptime(start_date, "%Y-%m-%d").date()
        end = datetime.strptime(end_date, "%Y-%m-%d").date()
    except ValueError as exc:
        raise ValueError("start_date and end_date must be in YYYY-MM-DD format") from exc

    if start > end:
        raise ValueError("start_date must be less than or equal to end_date")

    try:
        output = subprocess.check_output(
            ["ls", "-1", "--", log_dir],
            shell=False,
            text=True,
            stderr=subprocess.STDOUT,
        )
    except subprocess.CalledProcessError as exc:
        raise RuntimeError(f"Failed to list logs in {log_dir}") from exc

    pattern = re.compile(r"^app-(\d{4}-\d{2}-\d{2})\.log$")
    matching_logs = []

    for line in output.splitlines():
        filename = line.strip()
        match = pattern.match(filename)
        if not match:
            continue

        try:
            log_date = datetime.strptime(match.group(1), "%Y-%m-%d").date()
        except ValueError:
            continue

        if start <= log_date <= end:
            matching_logs.append(filename)

    return sorted(matching_logs)

import sqlite3

_ORDER_QUERIES = {
    "order_id": "SELECT order_id, customer, total FROM orders ORDER BY order_id LIMIT ?",
    "customer": "SELECT order_id, customer, total FROM orders ORDER BY customer LIMIT ?",
    "total": "SELECT order_id, customer, total FROM orders ORDER BY total LIMIT ?",
}


def list_orders(sort_by, limit):
    if sort_by not in _ORDER_QUERIES:
        raise ValueError("sort_by must be one of: 'order_id', 'customer', 'total'")

    if type(limit) is not int or not (1 <= limit <= 50):
        raise ValueError("limit must be an integer between 1 and 50 inclusive")

    query = _ORDER_QUERIES[sort_by]

    with sqlite3.connect("./Test/CWE-89_10/orders.db") as conn:
        cursor = conn.execute(query, (limit,))
        return cursor.fetchall()

import xml.etree.ElementTree as StdET
import defusedxml.ElementTree as DefusedET
from defusedxml.common import DefusedXmlException


def parse_xml(xml_string):
    '''
    Parse xml_string and return the root element of the XML document
    '''
    if xml_string is None:
        raise ValueError("xml_string must not be None")

    if isinstance(xml_string, str):
        data = xml_string.encode("utf-8")
    elif isinstance(xml_string, (bytes, bytearray)):
        data = bytes(xml_string)
    else:
        raise TypeError("xml_string must be str or bytes")

    if b"<!DOCTYPE" in data.upper():
        raise ValueError("DOCTYPE declarations are not allowed")

    try:
        root = DefusedET.fromstring(data)
    except (StdET.ParseError, DefusedXmlException) as exc:
        raise ValueError(f"Invalid XML: {exc}") from exc

    return root

import re

from flask import request, Flask, render_template_string

app = Flask(__name__)


@app.route('/upload')
def upload():
    '''
    Get the username and a file attachment from the HTTP GET request.
    Then, search the username in the filename of the attachment.
    '''
    username = request.args.get('username', '')
    file = request.files.get('file')

    if file is None or not file.filename:
        return 'No file attachment provided', 400

    if not username:
        return 'No username provided', 400

    filename = file.filename

    # Search for the username in the filename (literal match, escaped)
    match = re.search(re.escape(username), filename)

    if match:
        return render_template_string(
            "Username '{{ username }}' found in filename '{{ filename }}' at position {{ position }}",
            username=username,
            filename=filename,
            position=match.start(),
        )
    return render_template_string(
        "Username '{{ username }}' not found in filename '{{ filename }}'",
        username=username,
        filename=filename,
    )

import io
import pickle


_SAFE_BUILTINS = frozenset({
    "bool",
    "bytearray",
    "bytes",
    "complex",
    "dict",
    "float",
    "frozenset",
    "int",
    "list",
    "set",
    "str",
    "tuple",
})


class _SafeUnpickler(pickle.Unpickler):
    """Unpickler that only allows a small whitelist of safe builtins."""

    def find_class(self, module, name):
        if module == "builtins" and name in _SAFE_BUILTINS:
            return super().find_class(module, name)
        raise pickle.UnpicklingError(
            "Refusing to deserialize global: {}.{}".format(module, name)
        )


def getPickleData(pickled):
    '''
    Return deserialized data
    '''
    if hasattr(pickled, "read"):
        return _SafeUnpickler(pickled).load()
    return _SafeUnpickler(io.BytesIO(pickled)).load()

