import os
import re
import subprocess
from datetime import datetime


def list_logs_in_range(log_dir, start_date, end_date):
    if not isinstance(log_dir, str) or not log_dir:
        raise ValueError("log_dir must be a non-empty string")
    if not os.path.isdir(log_dir):
        raise NotADirectoryError(f"log_dir is not an existing directory: {log_dir}")

    date_fmt = "%Y-%m-%d"
    date_pat = re.compile(r"^\d{4}-\d{2}-\d{2}$")
    for label, value in (("start_date", start_date), ("end_date", end_date)):
        if not isinstance(value, str) or not date_pat.match(value):
            raise ValueError(f"{label} must be a string in YYYY-MM-DD format")

    try:
        start = datetime.strptime(start_date, date_fmt).date()
        end = datetime.strptime(end_date, date_fmt).date()
    except ValueError as exc:
        raise ValueError(f"Invalid date: {exc}") from exc

    if start > end:
        raise ValueError("start_date must be on or before end_date")

    # Safe: pass arguments as a list without shell=True to avoid command injection.
    try:
        output = subprocess.check_output(
            ["ls", log_dir],
            shell=False,
            stderr=subprocess.PIPE,
            text=True,
        )
    except subprocess.CalledProcessError as exc:
        stderr = (exc.stderr or "").strip()
        raise RuntimeError(f"Failed to list directory: {stderr}") from exc

    pattern = re.compile(r"^app-(\d{4}-\d{2}-\d{2})\.log$")
    matches = []
    for name in output.splitlines():
        name = name.strip()
        m = pattern.match(name)
        if not m:
            continue
        try:
            file_date = datetime.strptime(m.group(1), date_fmt).date()
        except ValueError:
            continue
        if start <= file_date <= end:
            matches.append(name)

    return sorted(matches)

import xml.etree.ElementTree as ET
from defusedxml import ElementTree as DefusedET
from defusedxml.common import DefusedXmlException


def parse_xml(xml_string):
    '''
    Parse xml_string and return the root element of the XML document
    '''
    if isinstance(xml_string, bytes):
        data = xml_string
    elif isinstance(xml_string, str):
        data = xml_string.strip()
    else:
        raise TypeError("xml_string must be a str or bytes object")

    if not data:
        raise ValueError("xml_string is empty")

    try:
        root = DefusedET.fromstring(data)
    except ET.ParseError as exc:
        raise ValueError(f"Invalid XML: {exc}") from exc
    except DefusedXmlException as exc:
        raise ValueError(f"Invalid XML: {exc}") from exc

    return root

import re

from flask import request, Flask, render_template_string

app = Flask(__name__)

_FOUND_TEMPLATE = (
    "Username '{{ username }}' found in filename '{{ filename }}' "
    "at position {{ position }}"
)
_NOT_FOUND_TEMPLATE = "Username '{{ username }}' not found in filename '{{ filename }}'"


@app.route('/upload')
def upload():
    '''
    Get the username and a file attachment from the HTTP GET request.
    Then, search the username in the filename of the attachment.
    '''
    username = request.args.get('username', '')

    attachment = request.files.get('attachment')
    if attachment is not None and attachment.filename:
        filename = attachment.filename
    else:
        filename = request.args.get('filename', '')

    if not username:
        return 'Missing username', 400
    if not filename:
        return 'Missing attachment filename', 400

    match = re.search(re.escape(username), filename)

    if match:
        return render_template_string(
            _FOUND_TEMPLATE,
            username=username,
            filename=filename,
            position=match.start(),
        )
    return render_template_string(
        _NOT_FOUND_TEMPLATE,
        username=username,
        filename=filename,
    )

